CREATE INDEX IF NOT EXISTS idx_calendar_slots_date_status ON public.calendar_slots (slot_date, status) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_slot_templates_active ON public.slot_templates (active) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_slot_exceptions_dates ON public.slot_exceptions (start_date, end_date) WHERE deleted_at IS NULL;

